 "content": "def transform(grid):
    w=len(grid[0])
    # Lower template (color 1), top objects grouped by distinct color.
    lo=[(r,c) for r in range(6,len(grid)) for c,v in enumerate(grid[r]) if v==1]
    r0=min(r for r,c in lo); c0=min(c for r,c in lo)
    lower={(r-r0,c-c0) for r,c in lo}
    # Match the top object having the same number of cells as the lower template.
    objs={}
    for r in range(5):
        for c,v in enumerate(grid[r]):
            if v not in (0,5): objs.setdefault(v,[]).append((r,c))
    col,pts=min(objs.items(),key=lambda item:abs(len(item[1])-len(lo)))
    a=min(r for r,c in pts); b=min(c for r,c in pts)
    upper={(r-a,c-b) for r,c in pts}
    h=max(r for r,c in upper)+1
    out=[[0]*w for _ in range(9)]
    # Output shows chosen top form followed by the lower template, aligned by center.
    lw=max(c for r,c in lower)+1; uw=max(c for r,c in upper)+1
    x0=(w-lw)//2; x1=x0+(lw-uw)//2
    for r,c in upper: out[1+r][x1+c]=col
    for r,c in lower: out[1+h+r][x0+c]=1
